                'appendsToAPropertyOfAnObject' => ['contracts.unsupported: Only assignments to local variables are allowed (no property, array or dynamic writes); appending is supported on a list built in the method ($list = []; $list[] = $value), or write $list = [...$list, $value].'],
                'appendsToAnInt' => ['contracts.unsupported: Appending to $n is only supported on a list, not on a int.'],
                'appendsToANullableList' => ['contracts.unsupported: Appending to $items, which may be null here'],
